// MENING HUDUDIM - Leaflet Map Integration for Uzbekistan

// Uzbekistan Boundaries
const UZBEKISTAN_BOUNDS = [
    [36.8, 55.8], // Southwest
    [45.8, 73.4]  // Northeast
];
const UZBEKISTAN_CENTER = [41.3775, 64.5853];

// Escape every value coming from the API before inserting it into HTML.
function escapeHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, function (ch) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch];
    });
}

// Only local links are generated by the API; reject anything else.
function safeUrl(url) {
    return (typeof url === 'string' && url.startsWith('/')) ? escapeHtml(url) : '#';
}

// Custom marker generator with status colors
function createStatusPin(status, iconClass) {
    let color = '#2563EB'; // new
    if (status === 'in_progress') color = '#F59E0B';
    else if (status === 'assigned') color = '#0284C7';
    else if (status === 'resolved') color = '#10B981';
    else if (status === 'rejected') color = '#EF4444';

    return L.divIcon({
        className: 'custom-map-pin',
        html: `
            <div style="
                background-color: ${color};
                width: 34px;
                height: 34px;
                border-radius: 50% 50% 50% 0;
                transform: rotate(-45deg);
                display: flex;
                align-items: center;
                justify-content: center;
                box-shadow: 0 4px 10px rgba(0,0,0,0.3);
                border: 2px solid #FFFFFF;
            ">
                <i class="${escapeHtml(iconClass || 'fa-solid fa-location-dot')}" style="transform: rotate(45deg); color: #FFFFFF; font-size: 13px;"></i>
            </div>
        `,
        iconSize: [34, 34],
        iconAnchor: [17, 34],
        popupAnchor: [0, -32]
    });
}

// Real administrative boundaries of Uzbekistan (state border + 14 regions).
let boundariesLoaded = false;

function loadUzbekistanBoundaries(map, options) {
    if (boundariesLoaded) return;
    boundariesLoaded = true;
    const opts = options || {};

    fetch('/api/regions-geojson/')
        .then(res => res.json())
        .then(data => {
            // State border first so the region polygons are painted above it.
            if (data.country && data.country.features && data.country.features.length) {
                L.geoJSON(data.country, {
                    interactive: false,
                    style: { color: '#1E40AF', weight: 3.2, opacity: 0.95, fill: false }
                }).addTo(map);
            }

            if (!data.regions || !data.regions.features) return;

            const layer = L.geoJSON(data.regions, {
                style: function (feature) {
                    const count = Number((feature.properties || {}).report_count) || 0;
                    return {
                        fillColor: count > 0 ? '#60A5FA' : '#DBEAFE',
                        fillOpacity: count > 0 ? 0.45 : 0.3,
                        color: '#FFFFFF',
                        weight: 1.4,
                        opacity: 0.95
                    };
                },
                onEachFeature: function (feature, polygon) {
                    const props = feature.properties || {};
                    const name = escapeHtml(props.name_uz || props.region_name || '');
                    const count = Number(props.report_count) || 0;

                    polygon.bindTooltip(
                        `<div class="uz-region-tooltip"><strong>${name}</strong><br><span>${count} ta murojaat</span></div>`,
                        { sticky: true, direction: 'top', className: 'uz-region-tooltip' }
                    );

                    if (!opts.interactive) return;

                    polygon.on('mouseover', function () {
                        polygon.setStyle({ fillOpacity: 0.6, weight: 2.2, color: '#2563EB' });
                    });
                    polygon.on('mouseout', function () {
                        layer.resetStyle(polygon);
                    });
                    polygon.on('click', function () {
                        const regionId = props.region_id;
                        const select = document.getElementById('filter-region');
                        if (regionId && select) {
                            select.value = String(regionId);
                            select.dispatchEvent(new Event('change'));
                        }
                        map.fitBounds(polygon.getBounds(), { padding: [30, 30] });
                    });
                }
            }).addTo(map);

            window.uzRegionsLayer = layer;
            if (opts.fit) {
                map.fitBounds(layer.getBounds(), { padding: [20, 20] });
            }
        })
        .catch(err => console.error('O‘zbekiston chegaralarini yuklashda xatolik:', err));
}

// 1. Interactive Form Location Picker Map
let pickerMapInstance = null;
let pickerMarkerInstance = null;

function initMapPicker(initialLat, initialLng) {
    const latField = document.getElementById('id_latitude');
    const lngField = document.getElementById('id_longitude');
    const lat = initialLat || (latField ? parseFloat(latField.value) : 41.2995);
    const lng = initialLng || (lngField ? parseFloat(lngField.value) : 69.2401);

    pickerMapInstance = L.map('map-picker', {
        maxBounds: UZBEKISTAN_BOUNDS,
        minZoom: 6,
        maxZoom: 19
    }).setView([lat, lng], 13);

    L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
        attribution: '&copy; OpenStreetMap | &copy; CARTO | Chegaralar: GeoJSON-Uzbekistan',
        maxZoom: 19
    }).addTo(pickerMapInstance);

    // Show the real country/region outlines as a reference while picking a point.
    loadUzbekistanBoundaries(pickerMapInstance, { interactive: false });

    pickerMarkerInstance = L.marker([lat, lng], {
        draggable: true,
        icon: createStatusPin('new', 'fa-solid fa-bullseye')
    }).addTo(pickerMapInstance);

    function updateCoords(newLat, newLng) {
        if (latField) latField.value = newLat.toFixed(6);
        if (lngField) lngField.value = newLng.toFixed(6);
        pickerMarkerInstance.setLatLng([newLat, newLng]);
        pickerMarkerInstance.bindPopup(`Tanlangan nuqta:<br><strong>${newLat.toFixed(5)}, ${newLng.toFixed(5)}</strong>`).openPopup();
    }

    pickerMapInstance.on('click', function (e) {
        updateCoords(e.latlng.lat, e.latlng.lng);
    });

    pickerMarkerInstance.on('dragend', function (e) {
        const pos = pickerMarkerInstance.getLatLng();
        updateCoords(pos.lat, pos.lng);
    });

    // Geolocation button
    const locateBtn = document.getElementById('btn-get-location');
    if (locateBtn && navigator.geolocation) {
        locateBtn.addEventListener('click', function () {
            locateBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin me-1"></i> Aniqlanmoqda...';
            navigator.geolocation.getCurrentPosition(
                function (pos) {
                    const uLat = pos.coords.latitude;
                    const uLng = pos.coords.longitude;
                    pickerMapInstance.setView([uLat, uLng], 16);
                    updateCoords(uLat, uLng);
                    locateBtn.innerHTML = '<i class="fa-solid fa-location-crosshairs me-1"></i> Mening joylashuvim';
                },
                function (err) {
                    alert("Geolokatsiyani aniqlab bo'lmadi. Iltimos, xaritadan qo'lda tanlang.");
                    locateBtn.innerHTML = '<i class="fa-solid fa-location-crosshairs me-1"></i> Mening joylashuvim';
                }
            );
        });
    }

    // When user changes Region in dropdown, auto-fly picker map to that region!
    const regionSelect = document.getElementById('id_region');
    if (regionSelect) {
        regionSelect.addEventListener('change', function () {
            const regId = this.value;
            if (regId) {
                fetch(`/locations/api/districts/${regId}/`)
                    .then(res => res.json())
                    .then(data => {
                        if (data.region && data.region.lat && data.region.lng) {
                            pickerMapInstance.flyTo([data.region.lat, data.region.lng], data.region.zoom || 11, {
                                animate: true,
                                duration: 1.2
                            });
                            updateCoords(data.region.lat, data.region.lng);
                        }
                    });
            }
        });
    }
}

// 2. Full Interactive Map with Filters & Smooth Region Flying
function initFullMap() {
    const map = L.map('full-map', {
        maxBounds: UZBEKISTAN_BOUNDS,
        minZoom: 5,
        maxZoom: 19
    }).setView(UZBEKISTAN_CENTER, 6);

    window.mainMap = map;

    L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
        attribution: '&copy; OpenStreetMap | &copy; CARTO | Chegaralar: GeoJSON-Uzbekistan | MENING HUDUDIM 🇺🇿',
        maxZoom: 19
    }).addTo(map);

    // Real Uzbekistan state border + all 14 region boundaries.
    loadUzbekistanBoundaries(map, { interactive: true, fit: true });

    let markersLayer = L.layerGroup().addTo(map);

    function loadReports() {
        const cat = document.getElementById('filter-category') ? document.getElementById('filter-category').value : '';
        const reg = document.getElementById('filter-region') ? document.getElementById('filter-region').value : '';
        const status = document.getElementById('filter-status') ? document.getElementById('filter-status').value : '';

        const params = new URLSearchParams();
        if (cat) params.append('category', cat);
        if (reg) params.append('region', reg);
        if (status) params.append('status', status);

        fetch(`/api/reports-geojson/?${params.toString()}`)
            .then(res => res.json())
            .then(data => {
                markersLayer.clearLayers();

                const bounds = [];
                data.reports.forEach(r => {
                    if (r.lat && r.lng) {
                        const pin = createStatusPin(r.status, r.category_icon);
                        const marker = L.marker([r.lat, r.lng], { icon: pin });

                        const popupHtml = `
                            <div style="min-width: 220px; font-family: inherit;">
                                ${r.image_url ? `<img src="${safeUrl(r.image_url)}" alt="" style="width: 100%; height: 120px; object-fit: cover; border-radius: 8px; margin-bottom: 8px;">` : ''}
                                <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
                                    <span class="badge bg-light text-dark border" style="font-family: monospace; font-size: 11px;">${escapeHtml(r.tracking_code)}</span>
                                    <span class="badge bg-${escapeHtml(r.status_badge)}">${escapeHtml(r.status_display)}</span>
                                </div>
                                <h6 style="font-size: 14px; font-weight: 700; margin: 6px 0; line-height: 1.3;">${escapeHtml(r.title)}</h6>
                                <p style="font-size: 12px; color: #64748B; margin-bottom: 8px;">
                                    <i class="fa-solid fa-location-dot me-1"></i> ${escapeHtml(r.region)}, ${escapeHtml(r.district)}
                                </p>
                                <a href="${safeUrl(r.detail_url)}" class="btn btn-sm btn-primary w-100" style="border-radius: 6px; font-size: 12px; font-weight: 600;">
                                    Batafsil ko'rish <i class="fa-solid fa-arrow-right ms-1"></i>
                                </a>
                            </div>
                        `;

                        marker.bindPopup(popupHtml);
                        markersLayer.addLayer(marker);
                        bounds.push([r.lat, r.lng]);
                    }
                });

                // If specific region selected, fly to it!
                if (reg) {
                    fetch(`/locations/api/districts/${reg}/`)
                        .then(res => res.json())
                        .then(d => {
                            if (d.region && d.region.lat && d.region.lng) {
                                map.flyTo([d.region.lat, d.region.lng], d.region.zoom || 10, {
                                    animate: true,
                                    duration: 1.2
                                });
                            }
                        });
                } else {
                    // Keep the whole country in view, including all reports.
                    let fit = window.uzRegionsLayer ? window.uzRegionsLayer.getBounds() : null;
                    if (bounds.length) {
                        const markerBounds = L.latLngBounds(bounds);
                        fit = fit ? fit.extend(markerBounds) : markerBounds;
                    }
                    if (fit) map.fitBounds(fit, { padding: [30, 30] });
                }
            })
            .catch(err => console.error("Xaritani yuklashda xatolik:", err));
    }

    loadReports();

    // Attach filter listeners
    ['filter-category', 'filter-region', 'filter-status'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('change', loadReports);
    });
}
